24	/// Cast DateTime64 to Int64 representation narrowed down (or scaled up) to any scale value defined in Impl.
25	class FunctionToUnixTimestamp64 : public IFunction
26	{
27	private:
28	    size_t target_scale;
29	    const char * name;
30	public:
31	    FunctionToUnixTimestamp64(size_t target_scale_, const char * name_)
32	        : target_scale(target_scale_), name(name_)
33	    {
34	    }
35	
36	    String getName() const override { return name; }
37	    size_t getNumberOfArguments() const override { return 1; }
38	    bool isVariadic() const override { return false; }
39	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return false; }
40	    bool useDefaultImplementationForConstants() const override { return true; }
41	
42	    DataTypePtr getReturnTypeImpl(const ColumnsWithTypeAndName & arguments) const override
43	    {
44	        if (!isDateTime64(arguments[0].type))
45	            throw Exception(ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT, "The only argument for function {} must be DateTime64", name);
46	
47	        return std::make_shared<DataTypeInt64>();
48	    }
49	
50	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t input_rows_count) const override
51	    {
52	        const auto & src = arguments[0];
53	        const auto & col = *src.column;
54	
55	        auto res_column = ColumnInt64::create(input_rows_count);
56	        auto & result_data = res_column->getData();
57	
58	        const auto & source_data = typeid_cast<const ColumnDecimal<DateTime64> &>(col).getData();
59	
60	        const Int32 scale_diff = typeid_cast<const DataTypeDateTime64 &>(*src.type).getScale() - target_scale;
61	        if (scale_diff == 0)
62	        {
63	            for (size_t i = 0; i < input_rows_count; ++i)
64	                result_data[i] = source_data[i];
65	        }
66	        else if (scale_diff < 0)
67	        {
68	            const Int64 scale_multiplier = DecimalUtils::scaleMultiplier<Int64>(-scale_diff);
69	            for (size_t i = 0; i < input_rows_count; ++i)
70	            {
71	                Int64 result_value = source_data[i];
72	                if (common::mulOverflow(result_value, scale_multiplier, result_value))
73	                    throw Exception("Decimal overflow in " + getName(), ErrorCodes::DECIMAL_OVERFLOW);
74	
75	                result_data[i] = result_value;
76	            }
77	        }
78	        else
79	        {
80	            const Int64 scale_multiplier = DecimalUtils::scaleMultiplier<Int64>(scale_diff);
81	            for (size_t i = 0; i < input_rows_count; ++i)
82	                result_data[i] = Int64(source_data[i]) / scale_multiplier;
83	        }
84	
85	        return res_column;
86	    }
